{
  "edges": {
    "Triggers__Maladaptive_Strategies": {
      "weight": 10,
      "explanation": "The vignette directly states that reminders and situations that bring up strong feelings lead her to avoid and resist them.",
      "quote": "\"she has been numbing her emotions, avoiding friends, giving up pleasant activities, steering clear of situations that bring up strong feelings, and resisting circumstances that remind her of the event\""
    },
    "Triggers__Threat": {
      "weight": 8,
      "explanation": "Sirens, reminders of victims, and future-related conversations are described as making her immediately more emotionally and physically strained and reinforcing danger.",
      "quote": "\"sirens, reminders of victims, and even conversations about the future\""
    },
    "Triggers__Memory": {
      "weight": 8,
      "explanation": "The vignette links cues and reminders to her intrusive recollections of the event, including sensory flashbacks when she thinks about it.",
      "quote": "\"Her memories of the event remain vivid and intrusive in a sensory way\""
    },
    "Triggers__Negative_Appraisals": {
      "weight": 6,
      "explanation": "The text suggests that reminders and future-related cues occur alongside beliefs that the world is dangerous and that she is permanently changed, but does not directly state the triggers cause those beliefs.",
      "quote": "\"sirens, reminders of victims, and even conversations about the future\""
    },
    "Negative_Appraisals__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "Her beliefs that the event changed her permanently and that the world is dangerous are presented as shaping her avoidant coping.",
      "quote": "\"These appraisals appear to intensify her sense of threat and shape the ways she tries to manage it.\""
    },
    "Negative_Appraisals__Threat": {
      "weight": 10,
      "explanation": "The vignette explicitly says her appraisals intensify her sense of threat.",
      "quote": "\"These appraisals appear to intensify her sense of threat\""
    },
    "Negative_Appraisals__Memory": {
      "weight": 8,
      "explanation": "Her appraisals are described as being reinforced by vivid memories and close, sensory recollection of the event.",
      "quote": "\"these memories helping to reinforce the sense that what happened was profoundly dangerous and has changed her permanently\""
    },
    "Negative_Appraisals__Triggers": {
      "weight": 2,
      "explanation": "The vignette mentions that her appraisals are shaped by the trauma memories, but it does not clearly state that negative appraisals generate triggers.",
      "quote": "\"these memories helping to reinforce\""
    },
    "Memory__Maladaptive_Strategies": {
      "weight": 6,
      "explanation": "Her intrusive memories and close access to the event are associated with avoidance and numbing as attempts to control distress.",
      "quote": "\"Her memories of the event remain vivid and intrusive\""
    },
    "Memory__Threat": {
      "weight": 8,
      "explanation": "The memories are said to reinforce the idea that the event was profoundly dangerous, which heightens threat.",
      "quote": "\"these memories helping to reinforce the sense that what happened was profoundly dangerous\""
    },
    "Memory__Negative_Appraisals": {
      "weight": 8,
      "explanation": "The vignette directly links her vivid memories with beliefs that the event was dangerous and permanently changed her.",
      "quote": "\"these memories helping to reinforce the sense that what happened was profoundly dangerous and has changed her permanently\""
    },
    "Memory__Triggers": {
      "weight": 6,
      "explanation": "The memories are described as being activated when she thinks about what happened, implying internal cues trigger them.",
      "quote": "\"when she thinks about what happened\""
    },
    "Threat__Maladaptive_Strategies": {
      "weight": 8,
      "explanation": "Her heightened sense of threat is followed by coping efforts aimed at controlling distress, including avoidance and numbing.",
      "quote": "\"These appraisals appear to intensify her sense of threat and shape the ways she tries to manage it.\""
    },
    "Threat__Memory": {
      "weight": 0,
      "explanation": "The vignette does not state that threat causes her intrusive memories.",
      "quote": ""
    },
    "Threat__Negative_Appraisals": {
      "weight": 0,
      "explanation": "The text does not clearly indicate that feeling threatened produces her negative beliefs.",
      "quote": ""
    },
    "Threat__Triggers": {
      "weight": 0,
      "explanation": "There is no direct evidence that her sense of threat creates triggers in the vignette.",
      "quote": ""
    },
    "Maladaptive_Strategies__Memory": {
      "weight": 0,
      "explanation": "The vignette does not say that avoidance or numbing alters her memories.",
      "quote": ""
    },
    "Maladaptive_Strategies__Negative_Appraisals": {
      "weight": 6,
      "explanation": "By narrowing her world and deepening isolation, her coping strategies seem to maintain the disconnection that fits her negative beliefs about being set apart.",
      "quote": "\"Over time, her attempts to control the distress seem to have deepened her isolation and left her feeling increasingly disconnected\""
    }
  }
}
